const msgs = $input.item.json.messages || [];
const me = ($env.SUPPORT_ADDRESS || '').toLowerCase();
const replied = msgs.some(m => {
  const hdrs = (m.payload && m.payload.headers) || [];
  const from = (hdrs.find(h => h.name === 'From') || {}).value || '';
  return me ? from.toLowerCase().includes(me) : /support|team|noreply/i.test(from);
});
return { json: { replied, messageCount: msgs.length } };
